CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE services (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
  pricing_type TEXT NOT NULL CHECK (pricing_type IN ('fixed','quotation')),
  base_price NUMERIC(12,2) NOT NULL CHECK (base_price >= 0), currency CHAR(3) NOT NULL DEFAULT 'USD',
  unit TEXT NOT NULL, estimated_duration_minutes INTEGER NOT NULL CHECK (estimated_duration_minutes > 0),
  image TEXT NOT NULL DEFAULT '', is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name TEXT NOT NULL, account_status TEXT NOT NULL DEFAULT 'active' CHECK(account_status IN ('active','guest','restricted','inactive')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE customer_contacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE RESTRICT, contact_type TEXT NOT NULL CHECK(contact_type IN ('phone','email')), contact_value TEXT NOT NULL, is_verified BOOLEAN NOT NULL DEFAULT FALSE, verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_customer_contact_lookup ON customer_contacts(contact_type,contact_value);
CREATE TABLE customer_addresses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE RESTRICT, label TEXT, address_details TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE service_packages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_id TEXT NOT NULL REFERENCES services(id) ON DELETE RESTRICT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', base_price NUMERIC(12,2) NOT NULL CHECK(base_price>=0), currency CHAR(3) NOT NULL, estimated_duration_minutes INTEGER NOT NULL CHECK(estimated_duration_minutes>0), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE workers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name TEXT NOT NULL, operational_status TEXT NOT NULL DEFAULT 'unavailable' CHECK(operational_status IN ('active','unavailable','suspended','inactive')), eligibility_status TEXT NOT NULL DEFAULT 'pending_review' CHECK(eligibility_status IN ('pending_review','eligible','restricted','suspended')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE worker_services (worker_id UUID NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE RESTRICT, qualification_status TEXT NOT NULL DEFAULT 'pending_review', verified_at TIMESTAMPTZ, verified_by UUID, PRIMARY KEY(worker_id,service_id));
CREATE TABLE worker_availability (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), worker_id UUID NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, weekday SMALLINT CHECK(weekday BETWEEN 0 AND 6), specific_date DATE, start_time TIME NOT NULL, end_time TIME NOT NULL, timezone TEXT NOT NULL DEFAULT 'Africa/Addis_Ababa', CHECK(start_time<end_time), CHECK(weekday IS NOT NULL OR specific_date IS NOT NULL));
CREATE TABLE bookings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reference TEXT NOT NULL UNIQUE, customer_id UUID REFERENCES customers(id) ON DELETE RESTRICT,
  service_id TEXT NOT NULL REFERENCES services(id) ON DELETE RESTRICT, service_name_snapshot TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','in_progress','completed','cancelled')),
  booking_source TEXT NOT NULL DEFAULT 'website' CHECK(booking_source IN ('website','phone','mobile_app','operations')),
  selection_method TEXT NOT NULL CHECK(selection_method IN ('customer_selected','operations_selected')), worker_preference TEXT,
  customer_name_snapshot TEXT NOT NULL, customer_phone_snapshot TEXT NOT NULL, customer_email_snapshot TEXT,
  address_snapshot TEXT NOT NULL, neighborhood TEXT NOT NULL, requested_start TIMESTAMPTZ NOT NULL,
  estimated_duration_minutes INTEGER NOT NULL CHECK(estimated_duration_minutes>0), scope_notes TEXT NOT NULL DEFAULT '',
  starting_estimate NUMERIC(12,2) CHECK(starting_estimate IS NULL OR starting_estimate>=0), agreed_amount NUMERIC(12,2) CHECK(agreed_amount IS NULL OR agreed_amount>=0), currency CHAR(3) NOT NULL,
  idempotency_key TEXT UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_bookings_status_created ON bookings(status,created_at DESC);
CREATE INDEX idx_bookings_phone ON bookings(customer_phone_snapshot);
CREATE INDEX idx_bookings_customer ON bookings(customer_id,created_at DESC);
CREATE TABLE booking_status_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT, old_status TEXT, new_status TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_booking_history_booking ON booking_status_history(booking_id,created_at);
CREATE TABLE booking_assignments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT, worker_id UUID NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, assignment_status TEXT NOT NULL, replaced_assignment_id UUID REFERENCES booking_assignments(id), customer_approved_at TIMESTAMPTZ, replacement_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE quotations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT, version INTEGER NOT NULL, total_amount NUMERIC(12,2) NOT NULL CHECK(total_amount>=0), currency CHAR(3) NOT NULL, scope_description TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','sent','accepted','rejected','expired')), valid_until TIMESTAMPTZ, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(booking_id,version));
CREATE TABLE quotation_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), quotation_id UUID NOT NULL REFERENCES quotations(id) ON DELETE RESTRICT, description TEXT NOT NULL, quantity NUMERIC(10,2) NOT NULL CHECK(quantity>0), unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0), line_total NUMERIC(12,2) NOT NULL CHECK(line_total>=0));
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT, amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), currency CHAR(3) NOT NULL, payment_stage TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('initiated','pending_verification','verified','failed','cancelled','refunded','partially_refunded')), provider TEXT, provider_reference TEXT, idempotency_key TEXT UNIQUE, verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE refunds (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payment_id UUID NOT NULL REFERENCES payments(id) ON DELETE RESTRICT, amount NUMERIC(12,2) NOT NULL CHECK(amount>0), currency CHAR(3) NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL, requested_by UUID, approved_by UUID, processed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE price_change_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT, previous_amount NUMERIC(12,2) NOT NULL, proposed_amount NUMERIC(12,2) NOT NULL, currency CHAR(3) NOT NULL, reason TEXT NOT NULL, scope_change TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'awaiting_customer_approval', customer_approved_at TIMESTAMPTZ, approved_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE contact_submissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', request_id TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE complaints (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID REFERENCES bookings(id) ON DELETE RESTRICT, reporter_type TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'normal', status TEXT NOT NULL DEFAULT 'open', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE complaint_actions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), complaint_id UUID NOT NULL REFERENCES complaints(id) ON DELETE RESTRICT, action TEXT NOT NULL, reason TEXT NOT NULL, decision_by UUID, reviewer_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE worker_restrictions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), worker_id UUID NOT NULL REFERENCES workers(id) ON DELETE RESTRICT, reason TEXT NOT NULL, risk_level TEXT NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'active', approved_by UUID, reinstatement_outcome TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), recipient TEXT NOT NULL, channel TEXT NOT NULL, template TEXT NOT NULL, related_entity TEXT, status TEXT NOT NULL DEFAULT 'pending', provider_reference TEXT, sent_at TIMESTAMPTZ, failure_details TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
